/* RC2 037 - Consolidated reconciliation run + financial account lifecycle evidence. */
USE [TAPortal]; GO
IF OBJECT_ID(N'dbo.ReconciliationRuns',N'U') IS NULL BEGIN
 CREATE TABLE dbo.ReconciliationRuns(Id uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() CONSTRAINT PK_ReconciliationRuns PRIMARY KEY,PartnerId uniqueidentifier NOT NULL,PartnerProviderConnectionId uniqueidentifier NOT NULL,FinancialAccountId uniqueidentifier NULL,RunType varchar(20) NOT NULL,WindowFrom datetime2(3) NOT NULL,WindowTo datetime2(3) NOT NULL,[Cursor] nvarchar(500) NULL,Status varchar(20) NOT NULL DEFAULT 'PENDING',ObservedCount int NOT NULL DEFAULT 0,InsertedCount int NOT NULL DEFAULT 0,ExistingCount int NOT NULL DEFAULT 0,FailedCount int NOT NULL DEFAULT 0,StartedAt datetime2(3) NULL,CompletedAt datetime2(3) NULL,ErrorMessage nvarchar(2000) NULL,CreatedAt datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_RRuns_Partner FOREIGN KEY(PartnerId) REFERENCES dbo.Partners(Id),CONSTRAINT FK_RRuns_Connection FOREIGN KEY(PartnerProviderConnectionId) REFERENCES dbo.PartnerProviderConnections(Id),CONSTRAINT FK_RRuns_Account FOREIGN KEY(FinancialAccountId) REFERENCES dbo.FinancialAccounts(Id),CONSTRAINT CK_RRuns_Type CHECK(RunType IN('SCHEDULED','MANUAL','RECOVERY')),CONSTRAINT CK_RRuns_Status CHECK(Status IN('PENDING','RUNNING','COMPLETED','PARTIAL','FAILED')));
 CREATE INDEX IX_RRuns_Work ON dbo.ReconciliationRuns(PartnerId,Status,WindowFrom DESC);
END
IF OBJECT_ID(N'dbo.FinancialAccountEvents',N'U') IS NULL CREATE TABLE dbo.FinancialAccountEvents(Id bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_FinancialAccountEvents PRIMARY KEY,FinancialAccountId uniqueidentifier NOT NULL,EventType varchar(30) NOT NULL,OldStatus varchar(20) NULL,NewStatus varchar(20) NULL,ProviderReference nvarchar(200) NULL,ActorType varchar(20) NOT NULL,ActorId uniqueidentifier NULL,Reason nvarchar(500) NULL,OccurredAt datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_FAE_Account FOREIGN KEY(FinancialAccountId) REFERENCES dbo.FinancialAccounts(Id),CONSTRAINT CK_FAE_Actor CHECK(ActorType IN('SYSTEM','USER','PROVIDER','WORKER')));
GO
PRINT '037-reconciliation-account-lifecycle.sql: OK'; GO